package mx.gob.sedesol.basegestor.gestionescolar.v2;

import static org.testng.Assert.assertEquals;
import static org.testng.Assert.assertFalse;
import static org.testng.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Date;
import java.util.List;

import org.testng.annotations.Test;

import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CausaIndisponibilidadOfertaV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CausaPendienteUnidadV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CodigoReglaCurricularV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.ContextoEvaluacionCurricularV2DTO;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.EstadoUnidadCurricularV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.EvaluacionCargaAcademicaV2DTO;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.ResultadoEvaluacionCurricularV2DTO;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.UnidadEvaluacionCurricularV2DTO;
import mx.gob.sedesol.basegestor.service.impl.gestionescolar.v2.EvaluacionCurricularV2ServiceImpl;

/** F4E-I-01 a F4E-I-30: matriz integrada de irregularidad y regularización. */
public class EvaluacionCurricularV2Fase4ETest {
    private final EvaluacionCurricularV2ServiceImpl service=new EvaluacionCurricularV2ServiceImpl();
    @Test public void f4EI01CeroReprobadasSinRezago(){EvaluacionCargaAcademicaV2DTO x=e(c(obligatoria(1L))).getEvaluacionCargaAcademica();assertFalse(x.getAplicaRn51());assertFalse(x.getAplicaRn52());assertFalse(x.getAplicaRn64());}
    @Test public void f4EI02UnaEsLeve(){assertLeve(e(c(reprobada(10L))).getEvaluacionCargaAcademica());}
    @Test public void f4EI03DosEsLeve(){assertLeve(e(c(reprobadas(20L,2))).getEvaluacionCargaAcademica());}
    @Test public void f4EI04TresEsLeveSinRn64(){EvaluacionCargaAcademicaV2DTO x=e(c(reprobadas(30L,3))).getEvaluacionCargaAcademica();assertLeve(x);assertFalse(x.getAplicaRn64());}
    @Test public void f4EI05CuatroEsSevero(){assertSevero(e(c(reprobadas(40L,4))).getEvaluacionCargaAcademica());}
    @Test public void f4EI06CincoEsSevero(){assertSevero(e(c(reprobadas(50L,5))).getEvaluacionCargaAcademica());}
    @Test public void f4EI07TransicionTresACuatroNoDejaLeve(){EvaluacionCargaAcademicaV2DTO leve=e(c(reprobadas(60L,3))).getEvaluacionCargaAcademica(),severo=e(c(reprobadas(60L,4))).getEvaluacionCargaAcademica();assertLeve(leve);assertSevero(severo);}
    @Test public void f4EI08TransicionCuatroATresConservaIrregular(){ResultadoEvaluacionCurricularV2DTO r=e(c(reprobadas(70L,3)));assertEquals(r.getSituacionAcademicaCalculada(),"IRREGULAR");assertLeve(r.getEvaluacionCargaAcademica());}
    @Test public void f4EI09TransicionDosAUnoSigueLeve(){assertLeve(e(c(reprobadas(80L,1))).getEvaluacionCargaAcademica());}
    @Test public void f4EI10UltimaAcreditadaDelegaRecuperacionARn13(){ResultadoEvaluacionCurricularV2DTO r=e(c(acreditada(90L)));assertFalse(r.getEvaluacionCargaAcademica().getAplicaRn51());assertTrue(r.getRecuperacionRegularidadEvaluada());}
    @Test public void f4EI11CincoACuatroSigueSevero(){assertSevero(e(c(reprobadas(100L,4))).getEvaluacionCargaAcademica());}
    @Test public void f4EI12CuatroACeroDesactivaSevero(){EvaluacionCargaAcademicaV2DTO x=e(c(acreditada(110L),acreditada(111L),acreditada(112L),acreditada(113L))).getEvaluacionCargaAcademica();assertFalse(x.getAplicaRn64());assertFalse(x.getAplicaRn52());}
    @Test public void f4EI13TresIntentosSonUnaReprobada(){UnidadEvaluacionCurricularV2DTO u=reprobada(120L);u.setIntentosFallidosHistoricosConfiables(Integer.valueOf(3));ResultadoEvaluacionCurricularV2DTO r=e(c(u));assertEquals(r.getCantidadReprobadasVigentes(),Integer.valueOf(1));assertLeve(r.getEvaluacionCargaAcademica());}
    @Test public void f4EI14CuatroUdsDistintasConIntentosSonCuatro(){List<UnidadEvaluacionCurricularV2DTO> us=reprobadas(130L,4);for(UnidadEvaluacionCurricularV2DTO u:us)u.setIntentosFallidosHistoricosConfiables(Integer.valueOf(3));ResultadoEvaluacionCurricularV2DTO r=e(c(us));assertEquals(r.getCantidadReprobadasVigentes(),Integer.valueOf(4));assertSevero(r.getEvaluacionCargaAcademica());}
    @Test public void f4EI15LeveConBajaParcialNoCambiaUmbral(){UnidadEvaluacionCurricularV2DTO b=baja(145L);List<UnidadEvaluacionCurricularV2DTO> us=reprobadas(140L,3);us.add(b);assertLeve(e(c(us)).getEvaluacionCargaAcademica());}
    @Test public void f4EI16LeveConNoCursadaNoCambiaUmbral(){List<UnidadEvaluacionCurricularV2DTO> us=reprobadas(150L,3);us.add(obligatoria(153L));ResultadoEvaluacionCurricularV2DTO r=e(c(us));assertEquals(r.getCantidadReprobadasVigentes(),Integer.valueOf(3));assertLeve(r.getEvaluacionCargaAcademica());}
    @Test public void f4EI17SeveroConBajaParcialNoCuentaCinco(){List<UnidadEvaluacionCurricularV2DTO> us=reprobadas(160L,4);us.add(baja(164L));ResultadoEvaluacionCurricularV2DTO r=e(c(us));assertEquals(r.getCantidadReprobadasVigentes(),Integer.valueOf(4));assertSevero(r.getEvaluacionCargaAcademica());}
    @Test public void f4EI18SinOfertaNoEliminaReprobacion(){List<UnidadEvaluacionCurricularV2DTO> us=reprobadas(170L,4);us.get(3).setOfertada(Boolean.FALSE);us.get(3).setCausaIndisponibilidadOferta(CausaIndisponibilidadOfertaV2.UD_NO_OFERTADA_PERIODO);ResultadoEvaluacionCurricularV2DTO r=e(c(us));assertEquals(r.getCantidadReprobadasVigentes(),Integer.valueOf(4));assertTrue(r.getEvaluacionCargaAcademica().getCausasIndisponibilidadRegularizacion().toString().contains("SIN_OFERTA"));}
    @Test public void f4EI19SinCupoNoEliminaReprobacion(){List<UnidadEvaluacionCurricularV2DTO> us=reprobadas(180L,4);us.get(3).setCupoDisponibleConocido(Boolean.FALSE);us.get(3).setCausaIndisponibilidadOferta(CausaIndisponibilidadOfertaV2.SIN_CUPO);ResultadoEvaluacionCurricularV2DTO r=e(c(us));assertEquals(r.getCantidadReprobadasVigentes(),Integer.valueOf(4));assertTrue(r.getEvaluacionCargaAcademica().getCausasIndisponibilidadRegularizacion().toString().contains("SIN_CUPO"));}
    @Test public void f4EI20LeveReutilizaRutaRn63(){ContextoEvaluacionCurricularV2DTO z=c(reprobada(190L));z.getUnidades().add(obligatoria(191L));EvaluacionCargaAcademicaV2DTO x=e(z).getEvaluacionCargaAcademica();assertLeve(x);assertTrue(x.getAplicaRn63());assertTrue(x.getUdsObligatoriasCompatibles().contains(Long.valueOf(191L)));}
    @Test public void f4EI21SeveroBloqueaObligatoriaNueva(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(200L,4));z.getUnidades().add(obligatoria(204L));EvaluacionCargaAcademicaV2DTO x=e(z).getEvaluacionCargaAcademica();assertSevero(x);assertTrue(x.getUdsObligatoriasNuevasBloqueadasRn64().contains(Long.valueOf(204L)));}
    @Test public void f4EI22SeveroPermiteOptativaSoloDespuesDePrioridad(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(210L,4));z.getUnidades().add(optativa(214L));EvaluacionCargaAcademicaV2DTO x=e(z).getEvaluacionCargaAcademica();assertTrue(x.getUdsReprobadasPrioritarias().contains(Long.valueOf(210L)));assertTrue(x.getUdsOptativasAdicionalesElegiblesRn64().contains(Long.valueOf(214L)));}
    @Test public void f4EI23MinimoExcepcionNoEliminaSevero(){List<UnidadEvaluacionCurricularV2DTO> us=reprobadas(220L,4);us.get(2).setOfertada(Boolean.FALSE);us.get(3).setOfertada(Boolean.FALSE);EvaluacionCargaAcademicaV2DTO x=e(c(us)).getEvaluacionCargaAcademica();assertSevero(x);assertTrue(x.getExcepcionMinimoAplicable());}
    @Test public void f4EI24SeveroPrevaleceQuinto(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(230L,4));z.setSemestreObjetivo(Integer.valueOf(5));z.setPeriodoNormativo("2027-1");z.setAvanceCondicionado(Boolean.TRUE);ResultadoEvaluacionCurricularV2DTO r=e(z);assertTrue(r.getEvaluacionCargaAcademica().getAvanceCondicionadoBloqueadoPorRn64());assertFalse(r.getAvanceCondicionado());}
    @Test public void f4EI25TerceroNoDetectaCtr01(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(240L,4));z.setPeriodoNormativo("2027-1");assertFalse(e(z).getEvaluacionCargaAcademica().getCtr01Rn61Procedente());}
    @Test public void f4EI26SeptimoNoDetectaCtr01(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(250L,4));z.setSemestreObjetivo(Integer.valueOf(7));z.setPeriodoNormativo("2027-1");assertFalse(e(z).getEvaluacionCargaAcademica().getCtr01Rn61Procedente());}
    @Test public void f4EI27DatosInsuficientesPropaganRevision(){EvaluacionCargaAcademicaV2DTO x=e(c(indeterminada(260L))).getEvaluacionCargaAcademica();assertTrue(x.getRequiereRevision());assertFalse(x.getAplicaRn51());assertFalse(x.getAplicaRn52());}
    @Test public void f4EI28DuplicadosNoDobleConteo(){UnidadEvaluacionCurricularV2DTO a=reprobada(270L),b=reprobada(270L);a.setBloque("B1");b.setBloque("B2");ResultadoEvaluacionCurricularV2DTO r=e(c(a,b,reprobada(271L),reprobada(272L),reprobada(273L)));assertEquals(r.getCantidadReprobadasVigentes(),Integer.valueOf(4));assertSevero(r.getEvaluacionCargaAcademica());}
    @Test public void f4EI29MismoContextoMismoResultado(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(280L,4));EvaluacionCargaAcademicaV2DTO a=e(z).getEvaluacionCargaAcademica(),b=e(z).getEvaluacionCargaAcademica();assertEquals(a.getCondicionRegularizacion(),b.getCondicionRegularizacion());assertEquals(a.getUdsReprobadasPrioritarias(),b.getUdsReprobadasPrioritarias());}
    @Test public void f4EI30SinEfectoProductivoYTrazasReconstruibles(){UnidadEvaluacionCurricularV2DTO u=reprobada(290L);ResultadoEvaluacionCurricularV2DTO r=e(c(u,reprobada(291L),reprobada(292L),reprobada(293L)));assertFalse(r.getEfectosProductivosAplicados());assertTrue(u.getOfertada());assertTrue(r.getReglasEvaluadas().contains(CodigoReglaCurricularV2.RN_1_2));assertTrue(r.getReglasEvaluadas().contains(CodigoReglaCurricularV2.RN_5_2));assertTrue(r.getReglasEvaluadas().contains(CodigoReglaCurricularV2.RN_6_3));assertTrue(r.getReglasEvaluadas().contains(CodigoReglaCurricularV2.RN_6_4));assertTrue(r.getReglasEvaluadas().contains(CodigoReglaCurricularV2.RN_4_3));}
    private void assertLeve(EvaluacionCargaAcademicaV2DTO x){assertTrue(x.getAplicaRn51());assertFalse(x.getAplicaRn52());assertFalse(x.getAplicaRn64());assertEquals(x.getCondicionRegularizacion(),"REZAGO_LEVE");assertEquals(x.getCargaMaximaNormativa(),Integer.valueOf(6));} private void assertSevero(EvaluacionCargaAcademicaV2DTO x){assertFalse(x.getAplicaRn51());assertTrue(x.getAplicaRn52());assertTrue(x.getAplicaRn64());assertEquals(x.getCondicionRegularizacion(),"REZAGO_SEVERO");assertEquals(x.getCargaMaximaNormativa(),Integer.valueOf(6));}
    private ResultadoEvaluacionCurricularV2DTO e(ContextoEvaluacionCurricularV2DTO z){return service.evaluarSombra(z);} private ContextoEvaluacionCurricularV2DTO c(UnidadEvaluacionCurricularV2DTO...us){ContextoEvaluacionCurricularV2DTO z=new ContextoEvaluacionCurricularV2DTO();z.setVersionReglas("PE2027-V1");z.setFechaEvaluacion(new Date(0L));z.setSemestreObjetivo(Integer.valueOf(3));z.setActividadAcademicaComprobada(Boolean.TRUE);z.setPermanenciaDentroLimiteComprobada(Boolean.TRUE);z.setDictaminacionEgresoConocida(Boolean.TRUE);z.setOportunidadesMejoraUtilizadas(Integer.valueOf(0));for(UnidadEvaluacionCurricularV2DTO u:us)z.getUnidades().add(u);return z;} private ContextoEvaluacionCurricularV2DTO c(List<UnidadEvaluacionCurricularV2DTO> us){return c(us.toArray(new UnidadEvaluacionCurricularV2DTO[us.size()]));}
    private List<UnidadEvaluacionCurricularV2DTO> reprobadas(Long i,int n){List<UnidadEvaluacionCurricularV2DTO> r=new ArrayList<UnidadEvaluacionCurricularV2DTO>();for(int x=0;x<n;x++)r.add(reprobada(Long.valueOf(i.longValue()+x)));return r;} private UnidadEvaluacionCurricularV2DTO obligatoria(Long i){return pendiente(i,"Obligatoria");} private UnidadEvaluacionCurricularV2DTO optativa(Long i){return pendiente(i,"Optativa");} private UnidadEvaluacionCurricularV2DTO reprobada(Long i){UnidadEvaluacionCurricularV2DTO u=pendiente(i,"Obligatoria");u.setEstado(EstadoUnidadCurricularV2.REPROBADA);u.setCausa(CausaPendienteUnidadV2.REPROBACION);u.setReprobacionVigenteConocida(Boolean.TRUE);u.setReprobacionPeriodoPrevioConocida(Boolean.TRUE);return u;} private UnidadEvaluacionCurricularV2DTO acreditada(Long i){UnidadEvaluacionCurricularV2DTO u=pendiente(i,"Obligatoria");u.setEstado(EstadoUnidadCurricularV2.ACREDITADA);u.setCausa(null);return u;} private UnidadEvaluacionCurricularV2DTO baja(Long i){UnidadEvaluacionCurricularV2DTO u=obligatoria(i);u.setEstado(EstadoUnidadCurricularV2.BAJA_PARCIAL);u.setCausa(CausaPendienteUnidadV2.BAJA_PARCIAL);return u;} private UnidadEvaluacionCurricularV2DTO indeterminada(Long i){UnidadEvaluacionCurricularV2DTO u=pendiente(i,"Obligatoria");u.setEstado(EstadoUnidadCurricularV2.NO_DETERMINADO);u.setCausa(null);return u;} private UnidadEvaluacionCurricularV2DTO pendiente(Long i,String t){UnidadEvaluacionCurricularV2DTO u=new UnidadEvaluacionCurricularV2DTO();u.setIdPrograma(i);u.setClave("UD"+i);u.setTipoUd(t);u.setEstado(EstadoUnidadCurricularV2.NO_CURSADA);u.setCausa(CausaPendienteUnidadV2.NO_CURSAMIENTO);u.setOfertada(Boolean.TRUE);u.setGrupoActivoConocido(Boolean.TRUE);u.setCupoDisponibleConocido(Boolean.TRUE);u.setSeleccionableOrigen(Boolean.TRUE);return u;}
}
